  match opcode {
    # ─────────────────────────────────────────────
    # call "state" → IR_STATE 노드
    # ─────────────────────────────────────────────
    "call" ->
      let func_name = match operands {
        [f | _] -> f,
        []      -> "unknown",
      }
      match func_name {
        "state" ->
          # state(N) → IR_STATE 노드, data=[N]
          let state_id = match operands {
            [_, id_str | _] -> parse_int_or(id_str, 0),
            _               -> 0,
          }
          let (st2, node_id) = add_node(st, "IR_STATE", [state_id])
          let st3 = match result {
            Some(reg) -> reg_bind(st2, reg, node_id),
            None      -> st2,
          }
          st3,

        # ─────────────────────────────────────────
        # call "consume" → IR_CONSUME 노드
        # ─────────────────────────────────────────
        "consume" ->
          let (st2, node_id) = add_node(st, "IR_CONSUME", [])
          # consume의 첫 인자 레지스터 → 이 노드의 입력
          let st3 = match operands {
            [_, src_reg | _] ->
              match reg_lookup(st2, src_reg) {
                Some(src_id) -> add_edge(st2, src_id, node_id, "CONSUMES"),
                None         -> add_error(st2, "consume: 미등록 레지스터 " + src_reg),
              },
            _ -> st2,
          }
          let st4 = match result {
            Some(reg) -> reg_bind(st3, reg, node_id),
            None      -> st3,
          }
          st4,

        # ─────────────────────────────────────────
        # call "evolve" → IR_EVOLVE 노드
        # ─────────────────────────────────────────
        "evolve" ->
          let time_delta = match operands {
            [_, _, dt_str | _] -> parse_int_or(dt_str, 1),
            [_, dt_str | _]    -> parse_int_or(dt_str, 1),
            _                  -> 1,
          }
          let (st2, node_id) = add_node(st, "IR_EVOLVE", [time_delta])
          let st3 = match operands {
            [_, src_reg | _] ->
              match reg_lookup(st2, src_reg) {
                Some(src_id) -> add_edge(st2, src_id, node_id, "EVOLVES"),
                None         -> add_error(st2, "evolve: 미등록 레지스터 " + src_reg),
              },
            _ -> st2,
          }
          let st4 = match result {
            Some(reg) -> reg_bind(st3, reg, node_id),
            None      -> st3,
          }
          st4,

        # ─────────────────────────────────────────
        # call "observe" → IR_OBSERVE 노드
        # ─────────────────────────────────────────
        "observe" ->
          let (st2, node_id) = add_node(st, "IR_OBSERVE", [])
          let st3 = match operands {
            [_, src_reg | _] ->
              match reg_lookup(st2, src_reg) {
                Some(src_id) -> add_edge(st2, src_id, node_id, "PRODUCES"),
                None         -> add_error(st2, "observe: 미등록 레지스터 " + src_reg),
              },
            _ -> st2,
          }
          let st4 = match result {
            Some(reg) -> reg_bind(st3, reg, node_id),
            None      -> st3,
          }
          st4,

        # ─────────────────────────────────────────
        # call "constrain" → IR_CONSTRAINT 노드
        # ─────────────────────────────────────────
        "constrain" ->
          let constraint_type = match operands {
            [_, ct | _] -> ct,
            _           -> "unknown",
          }
          let ct_id = constraint_type_id(constraint_type)
          let (st2, node_id) = add_node(st, "IR_CONSTRAINT", [ct_id])
          let st3 = match operands {
            [_, _, src_reg | _] ->
              match reg_lookup(st2, src_reg) {
                Some(src_id) -> add_edge(st2, src_id, node_id, "CONSTRAINS"),
                None         -> add_error(st2, "constrain: 미등록 레지스터 " + src_reg),
              },
            _ -> st2,
          }
          let st4 = match result {
            Some(reg) -> reg_bind(st3, reg, node_id),
            None      -> st3,
          }
          st4,

        # 그 외 함수 호출 → IR_OBSERVE로 래핑
        _ ->
          let (st2, node_id) = add_node(st, "IR_OBSERVE", [])
          let st3 = match result {
            Some(reg) -> reg_bind(st2, reg, node_id),
            None      -> st2,
          }
          st3,
      },

    # ─────────────────────────────────────────────
    # move → 레지스터 앨리어싱 (새 노드 없음)
    # ─────────────────────────────────────────────
    "move" ->
      match (operands, result) {
        ([src], Some(dst)) ->
          match reg_lookup(st, src) {
            Some(node_id) -> reg_bind(st, dst, node_id),
            None          ->
              # 상수 이동: 새 OBSERVE 노드
              let (st2, node_id) = add_node(st, "IR_OBSERVE", [])
              reg_bind(st2, dst, node_id),
          },
        _ -> st,
      },

    # ─────────────────────────────────────────────
    # 산술 연산 → IR_OBSERVE (값 흐름 표현)
    # ─────────────────────────────────────────────
    "add" | "sub" | "mul" | "div" | "mod" ->
      let (st2, node_id) = add_node(st, "IR_OBSERVE", [])
      # 두 입력 엣지
      let st3 = match operands {
        [l, r | _] ->
          let st_l = match reg_lookup(st2, l) {
            Some(lid) -> add_edge(st2, lid, node_id, "PRODUCES"),
            None      -> st2,
          }
          match reg_lookup(st_l, r) {
            Some(rid) -> add_edge(st_l, rid, node_id, "PRODUCES"),
            None      -> st_l,
          },
        _ -> st2,
      }
      let st4 = match result {
        Some(reg) -> reg_bind(st3, reg, node_id),
        None      -> st3,
      }
      st4,

    # ─────────────────────────────────────────────
    # ret → 마지막 노드에 TERMINAL 엣지
    # (자기 자신 → 자신: 종료 마킹)
    # ─────────────────────────────────────────────
    "ret" ->
      match operands {
        [src | _] ->
          match reg_lookup(st, src) {
            Some(node_id) -> add_edge(st, node_id, node_id, "TERMINAL"),
            None          -> st,
          },
        _ -> st,
      },

    # label, jmp, jmpz, jmpnz → 무시 (FVX는 제어흐름 그래프 아님)
    "label" | "jmp" | "jmpz" | "jmpnz" -> st,

    # alloca, gep, load, store → IR_OBSERVE
    "alloca" | "gep" | "load" | "store" ->
      let (st2, node_id) = add_node(st, "IR_OBSERVE", [])
      let st3 = match result {
        Some(reg) -> reg_bind(st2, reg, node_id),
        None      -> st2,
      }
      st3,

    # 나머지 → 에러 로그만
    _ ->
      add_error(st, "미처리 opcode: " + opcode),
  }

# ==============================================================================
# Part 5: 제약 타입 ID 변환
# ==============================================================================

function constraint_type_id(ct: String): Int =
  match ct {
    "NonNegative" -> 1,
    "Positive"    -> 2,
    "Finite"      -> 3,
    "Bounded"     -> 4,
    _             -> 0,
  }

# ==============================================================================
# Part 6: 정수 파싱 헬퍼
# ==============================================================================

function parse_int_or(s: String, default_val: Int): Int =
  match s.to_int() {
    Some(n) -> n,
    None    -> default_val,
  }

# ==============================================================================
# Part 7: 바이트코드 배열 일괄 변환
# ==============================================================================

# FreeJulia Bytecode 배열 → BridgeState
# 각 바이트코드를 순서대로 처리
function translate_all(bytecodes: [(String, [String], Option[String])]): BridgeState =
  let rec go(bcs: [(String, [String], Option[String])], st: BridgeState): BridgeState =
    match bcs {
      [] -> st,
      [(opcode, operands, result) | rest] ->
        let st2 = translate_bytecode(st, opcode, operands, result)
        go(rest, st2),
    }
  go(bytecodes, new_bridge_state())

# ==============================================================================
# Part 8: BridgeState → FVX IRGraph 문자열 출력
# ==============================================================================

function bridge_to_ir_string(st: BridgeState): String =
  let node_lines = map(st.nodes, fun (n: (Int, String, [Int])): String =
    let (id, ntype, data) = n
    let data_str = join(map(data, fun (x: Int): String = x.to_string()), ",")
    "  N" + id.to_string() + " [" + ntype + "] {" + data_str + "}"
  )
  let edge_lines = map(st.edges, fun (e: (Int, Int, String)): String =
    let (from_id, to_id, etype) = e
    "  N" + from_id.to_string() + " --[" + etype + "]--> N" + to_id.to_string()
  )
  let header = "IRGraph [nodes=" + length(st.nodes).to_string() +
               " edges=" + length(st.edges).to_string() + "]"
  let body   = join(node_lines + edge_lines, "\n")
  header + "\n" + body

# ==============================================================================
# Part 9: 오류 보고
# ==============================================================================

function bridge_ok(st: BridgeState): Bool =
  length(st.errors) == 0

function bridge_errors(st: BridgeState): String =
  join(st.errors, "\n")

function bridge_log(st: BridgeState): String =
  join(st.log, "\n")

