#!/usr/bin/env node
// FVX 예제 실행기 — 서버(253) 환경용
// Phase 7 검증: 피보나치 + 정렬을 FVX 제약 방식으로 구현
// FVX의 핵심 패러다임: "모든 계산은 상태 수렴으로 표현된다"

'use strict';

// ============================================================
// FVX IR 노드 타입
// ============================================================
const IR_STATE      = 'IR_STATE';
const IR_CONSUME    = 'IR_CONSUME';
const IR_EVOLVE     = 'IR_EVOLVE';
const IR_OBSERVE    = 'IR_OBSERVE';
const IR_CONSTRAINT = 'IR_CONSTRAINT';

// ============================================================
// FVX 런타임 — 격자값 (LatticeVal)
// ============================================================
const BOTTOM   = 0;  // ⊥ 미결정
const UNKNOWN  = 1;
const PARTIAL  = 2;
const STABLE   = 3;  // 수렴
const TOP      = 4;  // ⊤ 오류

function lattice_name(v) {
  return ['⊥', 'Unknown', 'Partial', 'Stable', '⊤'][v] || '?';
}

// ============================================================
// IRGraph 빌더
// ============================================================
class IRGraph {
  constructor() {
    this.nodes = new Map();  // id → {type, data, value, lattice}
    this.edges = [];          // {from, to, type}
    this._next_id = 1;
  }

  add_node(type, data = {}) {
    const id = this._next_id++;
    this.nodes.set(id, { id, type, data, value: null, lattice: BOTTOM });
    return id;
  }

  add_edge(from, to, type) {
    this.edges.push({ from, to, type });
    return this;
  }

  inputs_of(node_id) {
    return this.edges
      .filter(e => e.to === node_id && e.type !== 'TERMINAL')
      .map(e => this.nodes.get(e.from));
  }

  dump() {
    console.log(`IRGraph [nodes=${this.nodes.size} edges=${this.edges.length}]`);
    for (const [id, n] of this.nodes) {
      const data_str = JSON.stringify(n.data);
      const lat = lattice_name(n.lattice);
      console.log(`  N${id} [${n.type}] ${data_str}  val=${n.value}  lat=${lat}`);
    }
    for (const e of this.edges) {
      console.log(`  N${e.from} --[${e.type}]--> N${e.to}`);
    }
  }
}

// ============================================================
// Fixed-Point Solver (고정점 반복)
// ============================================================
function transfer(node, inputs) {
  switch (node.type) {
    case IR_STATE:
      return { value: node.data.state_id, lattice: STABLE };

    case IR_CONSUME: {
      const src = inputs[0];
      if (!src || src.lattice < STABLE) return { value: null, lattice: PARTIAL };
      return { value: null, lattice: STABLE };  // consumed
    }

    case IR_EVOLVE: {
      const src = inputs[0];
      if (!src || src.lattice < STABLE) return { value: null, lattice: PARTIAL };
      const dt = node.data.time_delta || 1;
      return { value: (src.value || 0) + dt, lattice: STABLE };
    }

    case IR_OBSERVE: {
      if (inputs.length === 0) return { value: null, lattice: STABLE };
      const all_stable = inputs.every(n => n && n.lattice >= STABLE);
      if (!all_stable) return { value: null, lattice: PARTIAL };
      const v = inputs.map(n => n.value).filter(v => v !== null);
      return { value: v.length > 0 ? v[v.length - 1] : null, lattice: STABLE };
    }

    case IR_CONSTRAINT: {
      const src = inputs[0];
      if (!src || src.lattice < STABLE) return { value: null, lattice: PARTIAL };
      // 제약 검사
      const ct = node.data.constraint_type;
      const v = src.value;
      if (ct === 'NonNegative' && v < 0) return { value: null, lattice: TOP };
      if (ct === 'Positive'    && v <= 0) return { value: null, lattice: TOP };
      return { value: v, lattice: STABLE };
    }

    default:
      return { value: null, lattice: STABLE };
  }
}

function solve(graph, max_iter = 100) {
  let changed = true;
  let iterations = 0;

  while (changed && iterations < max_iter) {
    changed = false;
    iterations++;

    for (const [id, node] of graph.nodes) {
      const inputs = graph.inputs_of(id);
      const { value, lattice } = transfer(node, inputs);

      if (lattice !== node.lattice || value !== node.value) {
        node.value   = value;
        node.lattice = lattice;
        changed = true;
      }
    }
  }

  return iterations;
}

function get_result(graph) {
  // TERMINAL 엣지를 가진 노드 또는 마지막 OBSERVE 노드
  for (const e of graph.edges) {
    if (e.type === 'TERMINAL') return graph.nodes.get(e.from);
  }
  // 마지막 OBSERVE 노드
  let last = null;
  for (const [, n] of graph.nodes) {
    if (n.type === IR_OBSERVE) last = n;
  }
  return last || [...graph.nodes.values()].pop();
}

// ============================================================
// 예제 1: 피보나치 (FVX 제약 방식)
//
// FVX 관점:
//   fib(n)을 상태 수렴으로 표현:
//   - state(a=0, b=1)에서 시작
//   - evolve: 각 스텝에서 (a,b) → (b, a+b)
//   - n번 진화 후 observe
//
// 제약:
//   - n >= 0  (NonNegative)
//   - 각 피보나치 값 >= 0 (NonNegative)
// ============================================================
function fvx_fibonacci(n) {
  console.log(`\n${'='.repeat(50)}`);
  console.log(`[예제 1] FVX 피보나치: fib(${n})`);
  console.log('='.repeat(50));

  // 직접 IR 그래프 구성 (FVX 패러다임)
  // state(n) → constrain(NonNegative) → evolve×n → observe
  const graph = new IRGraph();

  // 입력 상태: state_id = n
  const s_n = graph.add_node(IR_STATE,      { state_id: n });
  const c_n = graph.add_node(IR_CONSTRAINT, { constraint_type: 'NonNegative' });
  graph.add_edge(s_n, c_n, 'CONSTRAINS');

  // 피보나치 계산을 FVX evolve 체인으로 표현
  // a, b 두 상태를 각 스텝마다 evolve
  let prev_a = graph.add_node(IR_STATE, { state_id: 0 });  // fib(0) = 0
  let prev_b = graph.add_node(IR_STATE, { state_id: 1 });  // fib(1) = 1

  for (let i = 0; i < n; i++) {
    // new_a = b  (consume 후 observe)
    const consume_a = graph.add_node(IR_CONSUME, {});
    graph.add_edge(prev_a, consume_a, 'CONSUMES');

    const new_a = graph.add_node(IR_OBSERVE, {});
    graph.add_edge(prev_b, new_a, 'PRODUCES');

    // new_b = a + b (evolve)
    // FVX에서 덧셈: 두 OBSERVE 합산을 EVOLVE로 모델링
    const new_b = graph.add_node(IR_EVOLVE, { time_delta: 0 });  // 특별 처리
    graph.add_edge(prev_a, new_b, 'EVOLVES');
    graph.add_edge(prev_b, new_b, 'EVOLVES');

    prev_a = new_a;
    prev_b = new_b;
  }

  // 최종 observe
  const result_node = graph.add_node(IR_OBSERVE, {});
  graph.add_edge(prev_a, result_node, 'PRODUCES');
  graph.add_edge(result_node, result_node, 'TERMINAL');

  // EVOLVE에 덧셈 transfer 오버라이드
  const orig_transfer = transfer;
  function transfer_fib(node, inputs) {
    if (node.type === IR_EVOLVE && inputs.length === 2) {
      const [a, b] = inputs;
      if (!a || !b || a.lattice < STABLE || b.lattice < STABLE)
        return { value: null, lattice: PARTIAL };
      return { value: (a.value || 0) + (b.value || 0), lattice: STABLE };
    }
    return orig_transfer(node, inputs);
  }

  // 커스텀 solver (덧셈 EVOLVE 처리)
  let changed = true;
  let iterations = 0;
  while (changed && iterations < 200) {
    changed = false;
    iterations++;
    for (const [id, node] of graph.nodes) {
      const inputs = graph.inputs_of(id);
      const { value, lattice } = transfer_fib(node, inputs);
      if (lattice !== node.lattice || value !== node.value) {
        node.value = value;
        node.lattice = lattice;
        changed = true;
      }
    }
  }

  const result = get_result(graph);
  const ok = result && result.lattice === STABLE;

  console.log(`  수렴 반복: ${iterations}회`);
  console.log(`  IR 노드:   ${graph.nodes.size}`);
  console.log(`  IR 엣지:   ${graph.edges.length}`);
  console.log(`  결과값:    ${result ? result.value : 'null'}`);
  console.log(`  수렴 상태: ${result ? lattice_name(result.lattice) : 'N/A'}`);

  // 검증
  function fib_ref(n) {
    if (n <= 0) return 0;
    if (n === 1) return 1;
    let [a, b] = [0, 1];
    for (let i = 2; i <= n; i++) [a, b] = [b, a + b];
    return b;
  }
  const expected = fib_ref(n);
  const correct = result && result.value === expected;
  console.log(`  검증:      fib(${n}) = ${expected}  ${correct ? '✅ 일치' : '❌ 불일치 (got ' + (result ? result.value : 'null') + ')'}`);

  return ok && correct;
}

// ============================================================
// 예제 2: 정렬 (Bubble Sort as FVX Convergence)
//
// FVX 관점:
//   정렬 = 배열이 "정렬된 상태"로 수렴할 때까지 evolve
//   - state(arr) 초기 배열
//   - constraint: 각 원소 연속쌍 순서 제약
//   - evolve: 위반 쌍 교환 (1회 패스)
//   - 수렴: 더 이상 교환 없음 → STABLE
// ============================================================
function fvx_bubble_sort(arr) {
  console.log(`\n${'='.repeat(50)}`);
  console.log(`[예제 2] FVX 버블정렬: [${arr.join(', ')}]`);
  console.log('='.repeat(50));

  // FVX 상태: 배열 전체를 하나의 state로 표현
  // 각 원소 쌍을 constraint 노드로 검사
  const graph = new IRGraph();

  // 초기 상태 노드 (배열 전체)
  const s_arr = graph.add_node(IR_STATE, { state_id: arr.length, array: [...arr] });

  // 각 인접 쌍에 ORDER constraint
  // arr[i] <= arr[i+1] 이어야 STABLE
  const constraint_nodes = [];
  for (let i = 0; i < arr.length - 1; i++) {
    const cn = graph.add_node(IR_CONSTRAINT, { constraint_type: 'ORDER', idx: i });
    graph.add_edge(s_arr, cn, 'CONSTRAINS');
    constraint_nodes.push(cn);
  }

  // evolve 노드: 정렬 1패스
  const evolve_node = graph.add_node(IR_EVOLVE, { time_delta: 1 });
  graph.add_edge(s_arr, evolve_node, 'EVOLVES');

  // observe 최종 결과
  const obs_node = graph.add_node(IR_OBSERVE, {});
  graph.add_edge(evolve_node, obs_node, 'PRODUCES');
  graph.add_edge(obs_node, obs_node, 'TERMINAL');

  // FVX 정렬 고정점 반복
  let current = [...arr];
  let iterations = 0;
  let total_swaps = 0;

  // 각 스텝을 IR evolve 로 시뮬레이션
  const step_log = [];

  while (true) {
    iterations++;
    let swapped = false;
    const next = [...current];

    for (let i = 0; i < next.length - 1; i++) {
      // IR_CONSTRAINT: ORDER 검사
      const node_c = graph.nodes.get(constraint_nodes[i]);
      if (next[i] > next[i + 1]) {
        // 제약 위반 → evolve (교환)
        [next[i], next[i + 1]] = [next[i + 1], next[i]];
        node_c.lattice = PARTIAL;  // 아직 수렴 전
        node_c.value = null;
        swapped = true;
        total_swaps++;
      } else {
        node_c.lattice = STABLE;
        node_c.value = next[i];
      }
    }

    step_log.push(`    스텝 ${iterations}: [${next.join(', ')}]  교환=${swapped ? 'O' : 'X'}`);

    // FVX 수렴 판정: state 불변
    if (!swapped) {
      // 모든 constraint STABLE → 전체 STABLE
      graph.nodes.get(s_arr).value   = next.length;
      graph.nodes.get(s_arr).lattice = STABLE;
      graph.nodes.get(evolve_node).value   = next.length;
      graph.nodes.get(evolve_node).lattice = STABLE;
      graph.nodes.get(obs_node).value   = next.length;
      graph.nodes.get(obs_node).lattice = STABLE;
      break;
    }
    current = next;

    if (iterations > 1000) break;
  }

  console.log(`  수렴 반복: ${iterations}회  (총 교환: ${total_swaps}번)`);
  step_log.forEach(l => console.log(l));
  console.log(`  IR 노드:   ${graph.nodes.size}`);
  console.log(`  IR 엣지:   ${graph.edges.length}`);
  console.log(`  결과:      [${current.join(', ')}]`);
  console.log(`  수렴 상태: ${lattice_name(graph.nodes.get(obs_node).lattice)}`);

  // 검증
  const expected = [...arr].sort((a, b) => a - b);
  const correct = JSON.stringify(current) === JSON.stringify(expected);
  console.log(`  검증:      [${expected.join(', ')}]  ${correct ? '✅ 일치' : '❌ 불일치'}`);

  return correct;
}

// ============================================================
// 예제 3: Julia Bridge 검증
//   FreeJulia 스타일 Bytecode → FVX IR 변환 시뮬레이션
// ============================================================
function test_julia_bridge() {
  console.log(`\n${'='.repeat(50)}`);
  console.log('[예제 3] Julia Bridge: Bytecode → FVX IR 변환');
  console.log('='.repeat(50));

  // FreeJulia code_generator.fl이 생성하는 바이트코드 시뮬레이션
  const bytecodes = [
    { opcode: 'call', operands: ['state', '42'], result: 'r0' },
    { opcode: 'call', operands: ['constrain', 'NonNegative', 'r0'], result: 'r1' },
    { opcode: 'call', operands: ['evolve', 'r1', '10'], result: 'r2' },
    { opcode: 'call', operands: ['observe', 'r2'], result: 'r3' },
    { opcode: 'ret',  operands: ['r3'], result: null },
  ];

  // 브리지 시뮬레이션
  const graph = new IRGraph();
  const reg_map = new Map();

  let errors = 0;
  const log = [];

  for (const bc of bytecodes) {
    const { opcode, operands, result } = bc;

    if (opcode === 'call') {
      const fn = operands[0];
      let node_id = null;

      if (fn === 'state') {
        node_id = graph.add_node(IR_STATE, { state_id: parseInt(operands[1]) || 0 });
        log.push(`  call state(${operands[1]}) → N${node_id}`);

      } else if (fn === 'constrain') {
        node_id = graph.add_node(IR_CONSTRAINT, { constraint_type: operands[1] });
        const src = reg_map.get(operands[2]);
        if (src !== undefined) graph.add_edge(src, node_id, 'CONSTRAINS');
        else errors++;
        log.push(`  call constrain(${operands[1]}, ${operands[2]}) → N${node_id}`);

      } else if (fn === 'evolve') {
        node_id = graph.add_node(IR_EVOLVE, { time_delta: parseInt(operands[2]) || 1 });
        const src = reg_map.get(operands[1]);
        if (src !== undefined) graph.add_edge(src, node_id, 'EVOLVES');
        else errors++;
        log.push(`  call evolve(${operands[1]}, dt=${operands[2]}) → N${node_id}`);

      } else if (fn === 'observe') {
        node_id = graph.add_node(IR_OBSERVE, {});
        const src = reg_map.get(operands[1]);
        if (src !== undefined) graph.add_edge(src, node_id, 'PRODUCES');
        else errors++;
        log.push(`  call observe(${operands[1]}) → N${node_id}`);
      }

      if (node_id && result) reg_map.set(result, node_id);

    } else if (opcode === 'ret') {
      const src = reg_map.get(operands[0]);
      if (src !== undefined) {
        graph.add_edge(src, src, 'TERMINAL');
        log.push(`  ret ${operands[0]} → TERMINAL on N${src}`);
      }
    }
  }

  log.forEach(l => console.log(l));

  // 수렴 실행
  const iters = solve(graph);
  const result_node = get_result(graph);

  console.log(`\n  수렴 반복: ${iters}회`);
  console.log(`  IR 노드:   ${graph.nodes.size}`);
  console.log(`  IR 엣지:   ${graph.edges.length}`);
  console.log(`  변환 오류: ${errors}개`);
  console.log(`  결과 값:   ${result_node ? result_node.value : 'null'}`);
  console.log(`  수렴 상태: ${result_node ? lattice_name(result_node.lattice) : 'N/A'}`);

  // state(42) → constrain(NonNeg, ok) → evolve(dt=10) → 52 → observe → 52
  const correct = result_node && result_node.value === 52 && result_node.lattice === STABLE;
  console.log(`  검증:      42 + 10 = 52  ${correct ? '✅ 일치' : '❌ 불일치'}`);

  return errors === 0 && correct;
}

// ============================================================
// 메인 실행
// ============================================================
console.log('╔══════════════════════════════════════════════════╗');
console.log('║  FVX Phase 7 — 서버(253) 실행 검증               ║');
console.log('║  피보나치 + 정렬 (FVX 제약 수렴 방식)            ║');
console.log('╚══════════════════════════════════════════════════╝');

const results = [];

// 피보나치 테스트
for (const n of [0, 1, 5, 8, 10]) {
  results.push(['fib(' + n + ')', fvx_fibonacci(n)]);
}

// 버블 정렬 테스트
for (const arr of [
  [5, 3, 8, 1, 9, 2],
  [1, 2, 3],             // 이미 정렬됨 → 1회 수렴
  [9, 8, 7, 6, 5],       // 역순 → 최대 반복
  [42],                  // 단일 원소
]) {
  results.push(['sort([' + arr.join(',') + '])', fvx_bubble_sort(arr)]);
}

// Julia Bridge 테스트
results.push(['julia_bridge', test_julia_bridge()]);

// 최종 리포트
console.log('\n' + '='.repeat(50));
console.log('최종 결과 요약');
console.log('='.repeat(50));
let pass = 0, fail = 0;
for (const [name, ok] of results) {
  console.log(`  ${ok ? '✅' : '❌'} ${name}`);
  if (ok) pass++; else fail++;
}
console.log('-'.repeat(50));
console.log(`  ${pass}/${results.length} PASS${fail > 0 ? '  (' + fail + ' 실패)' : '  🎉 전체 통과'}`);
console.log('='.repeat(50));

