// ============================================================
// FVX 예제: range_check.fvx
// Phase I — 산술 불변성 증명
//
// 증명 목표:
//   루프 내 변수 x가 [0, 100] 범위를 절대 벗어나지 않음
//   x_next = (x + 1) mod 101  →  0 ≤ x ≤ 100 항상 유지
//
// FVX 패러다임:
//   - 상태 수렴이 아닌 "불변성 보존" 수렴
//   - Solver가 모든 evolve 경로에서 INVARIANT 위반 없음을 증명
// ============================================================

AXIOM {
    // A3: 제약 완전성 — 모든 상태는 제약을 만족해야 함
    DEFINE LIMIT = 100;
    DEFINE MODULO = 101;

    // 초기 상태
    ASSERT x_0 = 0;
    ASSERT x_0 >= 0;
    ASSERT x_0 <= LIMIT;

    // 전이 함수: x_next = (x + 1) mod MODULO
    DEFINE STEP(x) -> (x + 1) mod MODULO;
}

INVARIANT {
    // 루프 불변성: 모든 k에 대해 x_k ∈ [0, LIMIT]
    FORALL k: x_k >= 0;
    FORALL k: x_k <= LIMIT;

    // 단조성: STEP은 유한 순환 — 오버플로 없음
    ASSERT STEP(LIMIT) = 0;   // 100 → 0 (mod 101 wrap)
}

MATCH IR {
    // FreeJulia loop 구조와 매핑
    BRIDGE "FreeJulia::Loop_Counter";
    NODE   IR_STATE  { state_id: 0 };         // x = 0
    EVOLVE IR_EVOLVE { time_delta: 1 };        // +1 per step
    CLAMP  IR_CONSTRAINT { type: "Bounded",
                           lower: 0,
                           upper: 100 };
}

SOLVE {
    STRATEGY FixedPoint;
    SCHEDULE PriorityQueue;
    MAX_ITER 200;

    // 수렴 조건: STEP(x) = x  (mod 101 순환 = 고정점 없음)
    // → 대신 INVARIANT 위반 없음을 고정점으로 정의
    CONVERGE_ON INVARIANT_HOLDS;
}

PROOF {
    // Tarski 고정점 정리 적용:
    //   격자 L = {0..100} (완전 격자)
    //   f(x) = (x+1) mod 101 은 L → L 단조 함수
    //   → L 위에서 INVARIANT는 항상 유지됨 (귀납법)
    //
    // Base:    x_0 = 0  →  0 ∈ [0,100]  ✓
    // Step:    x_k ∈ [0,100]  →  STEP(x_k) ∈ [0,100]  ✓
    //          STEP(100) = 0  ∈ [0,100]  ✓ (wrap)
    // QED.
    EXPECTED STABLE;
    EXPECTED NO_VIOLATION;
}

