    FORALL i, j where i < j:
        AFTER_CONVERGENCE: array[i] <= array[j];
}

MATCH IR {
    // FreeJulia sort 구조와 매핑
    BRIDGE "FreeJulia::BubbleSort";

    // 초기 상태 노드
    NODE   IR_STATE  { state_id: 6, array: [5,3,8,1,9,2] };

    // 인접 쌍 ORDER 제약 (N-1 = 5개)
    REPEAT N-1:
        CONSTRAINT IR_CONSTRAINT { type: "ORDER", idx: i };

    // 매 패스마다 evolve (swap 실행)
    EVOLVE IR_EVOLVE { time_delta: 1, op: "swap_if_violated" };

    // 최종 관찰
    OBSERVE IR_OBSERVE {};
}

SOLVE {
    STRATEGY FixedPoint;
    SCHEDULE Worklist;      // 위반 쌍만 재처리 (AC-3 변형)
    MAX_ITER 50;

    // 수렴 조건: 모든 ORDER constraint가 STABLE
    CONVERGE_ON ALL_CONSTRAINTS_STABLE;
}

PROOF {
    // Termination 증명:
    //   measure φ(k) = |{(i,j): i<j ∧ array[i] > array[j]}| (역전 쌍 수)
    //   매 evolve에서 φ 감소 (swap은 역전 1개 이상 제거)
    //   φ ≥ 0  →  유한 스텝 내 φ = 0  →  수렴
    //
    // Correctness 증명:
    //   φ = 0  ↔  FORALL i<j: array[i] ≤ array[j]  (단조 증가)
    //   φ = 0  ↔  모든 ORDER constraint STABLE
    //   고정점 = 정렬 완료 상태  QED.
    //
    // Swap 전후 대소관계 추적:
    //   Before swap(i): array[i] > array[i+1]
    //   After  swap(i): array[i] < array[i+1]  (ORDER constraint 복구)
    //   → ORDER(i) PARTIAL → STABLE 전이

    EXPECTED STABLE;
    EXPECTED NO_VIOLATION;
    EXPECTED SORTED;
}

