// ============================================================
// FVX 예제: fib_safety.fvx
// Phase I — 재귀 정지 문제 및 자원 안전성 증명
//
// 증명 목표:
//   1. fib(n) 계산의 재귀 깊이 ≤ n  (스택 오버플로 없음)
//   2. DAG 전개: 순환 없이 의존성 그래프가 해소됨
//   3. 자원 보존: fib(n) 계산에 필요한 노드 수 = 2n-1
//
// FVX 패러다임:
//   - 재귀 = DAG evolve 체인 (순환 없음)
//   - 스택 = 자원 소비 추적 (A2: 자원 보존 공리)
//   - 정지 = DAG 말단 노드 수렴 (고정점)
// ============================================================

AXIOM {
    // A1: 상태 존재
    DEFINE n = 10;           // 입력값 (검증 대상)
    DEFINE MAX_DEPTH = 10;   // 허용 최대 재귀 깊이

    // A2: 자원 보존 — 재귀 호출 수
    //     fib(n)의 전체 함수 호출 수 = 2*fib(n+1) - 1
    DEFINE CALL_COUNT(n) -> 2 * fib(n+1) - 1;

    // 피보나치 점화식
    DEFINE fib(0) = 0;
    DEFINE fib(1) = 1;
    DEFINE fib(n) = fib(n-1) + fib(n-2)  WHERE n > 1;

    // A3: 깊이 제약
    ASSERT MAX_DEPTH >= n;
    CONSTRAINT DEPTH_BOUND: recursion_depth <= MAX_DEPTH;

    // A4: 시간 단조성 — 각 서브문제 크기 감소
    //     fib(k)는 fib(k-1), fib(k-2)에 의존 (k 감소)
    ASSERT SUBPROBLEM_DECREASES;
}

INVARIANT {
    // 깊이 불변성: 재귀 스택 깊이는 n을 초과하지 않음
    FORALL k: call_stack_depth(fib(k)) <= k;

    // DAG 불변성: 의존성 그래프에 순환 없음
    ACYCLIC dependency_graph;

    // 자원 불변성: 생성된 IR 노드 수 ≤ 2n+1
    node_count <= 2*n + 1;
}

MATCH IR {
    // fib(n) → fib(n-1) + fib(n-2) 전개
    BRIDGE "FreeJulia::Fibonacci_Recursive";

    // 기저 케이스 (말단 노드)
    NODE IR_STATE { state_id: 0, label: "fib_base_0" };
    NODE IR_STATE { state_id: 1, label: "fib_base_1" };

    // 재귀 전개 (각 단계 = EVOLVE)
    UNFOLD n TIMES:
        NODE   IR_EVOLVE { time_delta: 0, op: "fib_add" };
        EDGE   EVOLVES from fib(k-1) to fib(k);
        EDGE   EVOLVES from fib(k-2) to fib(k);

    // 결과 관찰
    OBSERVE IR_OBSERVE { label: "fib_result" };
}

SOLVE {
    STRATEGY FixedPoint;
    SCHEDULE TopDown;        // 큰 문제 → 작은 문제 (메모이제이션)
    MAX_ITER 100;

    // 수렴 조건: 모든 IR_STATE 노드 STABLE
    CONVERGE_ON ALL_STATES_STABLE;

    // 순환 감지: SCC 검사
    DETECT_CYCLE {
        ON_FOUND -> ABORT("순환 의존성 발견: 정지 불가");
        EXPECTED NO_CYCLE;
    }
}

PROOF {
    // Termination (정지 증명):
    //   measure μ(k) = k  (감소 수열)
    //   fib(k) 계산은 fib(k-1), fib(k-2)에 의존 (μ 감소)
    //   기저: fib(0) = 0, fib(1) = 1  (즉시 STABLE)
    //   → 유한 스텝 내 모든 노드 STABLE  QED.
    //
    // Stack Safety (스택 안전성):
    //   재귀 깊이 = 의존성 DAG의 최장 경로 = n
    //   n ≤ MAX_DEPTH = 10  →  스택 오버플로 없음  QED.
    //
    // DAG 증명:
    //   fib(k)는 fib(k-1), fib(k-2)에만 의존
    //   k-1 < k, k-2 < k  →  역방향 엣지 없음
    //   → 의존성 그래프 = DAG  QED.
    //
    // 자원 사용:
    //   IR 노드 수 = 2 + (n-1)*2 + 1 = 2n+1
    //   fib(10): 21개 노드, 깊이 10, 호출 177회

    EXPECTED STABLE;
    EXPECTED NO_CYCLE;
    EXPECTED DEPTH_OK;
    EXPECTED fib(10) = 55;
}

