// ============================================================
// FVX × Mandate-DB — 트랜잭션 공리 명세
// bridge/mandate_db_axioms.fvx
//
// Mandate-DB 구조:
//   MandateRecord { seq, timestamp, op, key, value,
//                   prev_hash, hash, server_id, is_tombstone }
//   LogStore { records[], count, next_seq, last_hash }
//
// FVX 공리 매핑:
//   A1 (상태 존재)   ← seq 단조 증가 (레코드 ID 공간)
//   A2 (자원 보존)   ← Append-Only (삭제 없음, Tombstone만)
//   A3 (제약 완전성) ← 해시 체인 무결성 (prev_hash 연속성)
//   A4 (시간 단조성) ← seq k+1 > seq k (시간 역행 없음)
// ============================================================

AXIOM {
    // ── A1: 레코드 존재 공간 ──────────────────────────────
    // 모든 seq는 [1, MAX_RECORDS] 범위 내에 존재
    DEFINE MAX_RECORDS = 10000;
    ASSERT seq >= 1;
    ASSERT seq <= MAX_RECORDS;

    // ── A2: Append-Only 자원 보존 ─────────────────────────
    // 레코드는 추가만 가능, 물리 삭제 없음
    // 삭제 = is_tombstone=1 레코드 추가
    ASSERT count_monotone_increasing;      // count 는 감소 불가
    ASSERT no_physical_delete;             // records[i] 수정 불가

    // ── A3: 해시 체인 무결성 ──────────────────────────────
    // 각 레코드의 prev_hash = 직전 레코드의 hash
    FORALL i where i > 0:
        CONSTRAINT CHAIN(i): records[i].prev_hash == records[i-1].hash;
    ASSERT records[0].prev_hash == "GENESIS";

    // ── A4: seq 단조 증가 (시간 역행 없음) ───────────────
    FORALL i where i > 0:
        CONSTRAINT MONOTONE(i): records[i].seq == records[i-1].seq + 1;

    // ── 연산 유효성 ───────────────────────────────────────
    DEFINE OP_SET    = 1;
    DEFINE OP_DELETE = 2;
    FORALL i: records[i].op IN {OP_SET, OP_DELETE};

    // ── Tombstone 일관성 ──────────────────────────────────
    FORALL i:
        CONSTRAINT TOMBSTONE(i):
            records[i].op == OP_DELETE IMPLIES records[i].is_tombstone == 1;
    FORALL i:
        CONSTRAINT SET_ALIVE(i):
            records[i].op == OP_SET IMPLIES records[i].is_tombstone == 0;
}

INVARIANT {
    // 읽기 일관성: GET(key) = 가장 최신 SET(key) 값
    // (Tombstone 이후 GET → NotFound)
    FORALL key:
        AFTER latest_tombstone(key):
            engine_get(key).found == 0;

    // Lost Update 없음: 같은 seq에 두 개의 쓰기 불가
    FORALL i, j where i != j:
        records[i].seq != records[j].seq;

    // Dirty Read 없음: 커밋되지 않은 seq는 읽기 불가
    // (Mandate-DB는 Append 즉시 커밋 → seq 존재 = 커밋 완료)
    FORALL read_op:
        read_op.seq <= store.next_seq - 1;
}

MATCH IR {
    BRIDGE "MandateDB::LogStore";

    // log_append → IR_STATE(seq) + IR_CONSTRAINT(chain)
    NODE   IR_STATE      { state_id: "seq", monotone: true };
    EVOLVE IR_EVOLVE     { op: "seq_increment", time_delta: 1 };
    CONSTRAINT IR_CONSTRAINT { type: "CHAIN",    field: "prev_hash" };
    CONSTRAINT IR_CONSTRAINT { type: "MONOTONE", field: "seq" };

    // engine_get → IR_OBSERVE (역순 탐색 최신값)
    OBSERVE IR_OBSERVE   { op: "latest_by_key" };
}

SOLVE {
    STRATEGY FixedPoint;
    SCHEDULE Worklist;
    MAX_ITER 10000;   // MAX_RECORDS 상한

    DETECT_CYCLE {
        ON_FOUND -> ABORT("해시 체인 순환: 데이터 위변조 감지");
        EXPECTED NO_CYCLE;
    }

    CONVERGE_ON ALL_CONSTRAINTS_STABLE;
}

PROOF {
    // Append-Only 정지 증명:
    //   count 단조 증가, count ≤ MAX_RECORDS
    //   → 유한 스텝 내 수렴 (μ = MAX_RECORDS - count)

    // 해시 체인 무결성:
    //   records[0].prev_hash = "GENESIS" (기저)
    //   records[i].prev_hash = records[i-1].hash (귀납)
    //   → 변조 시 CHAIN constraint 위반 → TOP 즉시

    // Lost Update 불가:
    //   seq = next_seq (단조 증가), 충돌 불가
    //   → MONOTONE constraint 위반 시 TOP

    EXPECTED STABLE;
    EXPECTED NO_VIOLATION;
    EXPECTED NO_CYCLE;
}

