// ============================================================
// FVX × FreeJulia — 정적 분석기 공리 명세
// bridge/freejulia_static.fvx
//
// 파이프라인:
//   FreeLang 소스 (.fl)
//     → FreeJulia code_generator.fl (Bytecode 생성)
//     → julia_bridge.fl (FVX IR 변환)
//     → FVX Solver (공리 검증)
//     → 런타임 에러 없음 증명 or 경고 출력
//
// 검증 대상:
//   1. 타입 안전성: 모든 연산의 입출력 타입 일치
//   2. 스택 안전성: 재귀 깊이 상한 보장
//   3. 무한루프 방지: evolve 체인의 고정점 도달 보장
//   4. Null 안전성: None 값이 언래핑되지 않음
// ============================================================

AXIOM {
    // ── 타입 안전성 공리 ──────────────────────────────────
    // 모든 IR_OBSERVE 입력은 동일 타입이어야 함
    FORALL node where node.type == IR_OBSERVE:
        ALL_INPUTS_SAME_TYPE(node);

    // IR_EVOLVE time_delta ≥ 0 (역행 없음)
    FORALL node where node.type == IR_EVOLVE:
        ASSERT node.data.time_delta >= 0;

    // ── 스택 안전성 공리 ──────────────────────────────────
    DEFINE MAX_CALL_DEPTH = 100;
    FORALL call_chain:
        CONSTRAINT DEPTH(call_chain):
            length(call_chain) <= MAX_CALL_DEPTH;

    // ── 종료 보장 공리 ────────────────────────────────────
    // 모든 evolve 체인은 유한 고정점에 도달
    FORALL evolve_chain:
        EXISTS fixpoint: converges_in(evolve_chain, fixpoint);

    // ── None 안전 공리 ────────────────────────────────────
    // IR_CONSTRAINT 입력이 None이면 PARTIAL (절대 언래핑 안 함)
    FORALL node where node.type == IR_CONSTRAINT:
        IF input.value == None THEN node.lattice <= PARTIAL;
}

INVARIANT {
    // 컴파일 후 런타임 에러 없음
    NO_RUNTIME_TYPE_ERROR;
    NO_STACK_OVERFLOW;
    NO_INFINITE_LOOP;
    NO_NULL_DEREF;

    // FreeJulia IR → FVX IR 변환 손실 없음
    BIJECTIVE julia_bridge;
}

MATCH IR {
    BRIDGE "FreeJulia::CodeGenerator";

    // Bytecode 스트림 → FVX IR (julia_bridge.fl 활용)
    TRANSLATE {
        "call state"     -> IR_STATE;
        "call consume"   -> IR_CONSUME;
        "call evolve"    -> IR_EVOLVE;
        "call observe"   -> IR_OBSERVE;
        "call constrain" -> IR_CONSTRAINT;
        "move"           -> ALIAS;
        "ret"            -> TERMINAL;
    }

    // 정적 분석 체크포인트
    CHECK_AT IR_OBSERVE:   TYPE_CONSISTENCY;
    CHECK_AT IR_EVOLVE:    TERMINATION;
    CHECK_AT IR_CONSTRAINT: NULL_SAFETY;
}

SOLVE {
    STRATEGY FixedPoint;
    SCHEDULE Hybrid;      // 작은 함수: EAGER, 재귀: LAZY
    MAX_ITER 500;

    // 분석 모드: 실행 없이 증명만
    MODE StaticAnalysis;

    DETECT_CYCLE {
        // 순환 의존성 = 잠재적 무한루프
        ON_FOUND -> WARN("잠재적 무한루프 감지: " + cycle_path);
        EXPECTED NO_CYCLE;
    }

    CONVERGE_ON ALL_STATES_STABLE;
}

PROOF {
    // 타입 안전성:
    //   모든 IR_OBSERVE 입력 타입이 STABLE 상태에서 일치
    //   → 런타임 타입 에러 불가

    // 스택 안전성:
    //   모든 재귀 체인의 μ(k) = depth 감소 수열
    //   depth ≤ MAX_CALL_DEPTH = 100
    //   → 스택 오버플로 불가

    // 종료 보장:
    //   DAG 검증 통과 = 순환 없음
    //   순환 없음 = 유한 evolve 체인
    //   → 무한루프 불가

    EXPECTED STABLE;
    EXPECTED NO_VIOLATION;
    EXPECTED STATIC_SAFE;
}

