#!/usr/bin/env node
// ============================================================
// FVX 연동 통합 테스트
// bridge/integration_test.js
//
// A. Mandate-DB 트랜잭션 공리 검증
// B. FreeJulia 정적 분석기 파이프라인
// ============================================================
'use strict';

const LAT = { BOTTOM:0, PARTIAL:1, STABLE:2, TOP:3 };
const LN  = ['⊥','Partial','Stable','⊤'];

// ─────────────────────────────────────────────────────────
// IRGraph (공통)
// ─────────────────────────────────────────────────────────
class IRGraph {
  constructor(name) {
    this.name  = name;
    this.nodes = new Map();
    this.edges = [];
    this._nid  = 1;
  }
  node(type, data={}) {
    const id = this._nid++;
    this.nodes.set(id, {id, type, data, value:null, lat:LAT.BOTTOM});
    return id;
  }
  edge(f,t,type) { this.edges.push({from:f,to:t,type}); return this; }
  inputs(nid) {
    return this.edges
      .filter(e=>e.to===nid && e.type!=='TERMINAL')
      .map(e=>this.nodes.get(e.from));
  }
}

function solve(g, transfer_fn, max=500) {
  let changed=true, iters=0;
  while(changed && iters<max) {
    changed=false; iters++;
    for(const [,n] of g.nodes) {
      const {value,lat} = transfer_fn(n, g.inputs(n.id));
      if(lat!==n.lat||value!==n.value){n.value=value;n.lat=lat;changed=true;}
    }
  }
  return iters;
}

function top_nodes(g) {
  return [...g.nodes.values()].filter(n=>n.lat===LAT.TOP);
}

// ─────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════
// A. Mandate-DB 트랜잭션 공리 검증
// ═══════════════════════════════════════════════════════
// ─────────────────────────────────────────────────────────

// Mandate-DB 시뮬레이터
class MandateDB {
  constructor() {
    this.records = [];
    this.next_seq = 1;
    this.last_hash = 'GENESIS';
  }
  _hash(seq, key, val, prev) {
    let h = seq * 31;
    for(const c of key)   h = (h*31 + c.charCodeAt(0)) | 0;
    for(const c of val)   h = (h*17 + c.charCodeAt(0)) | 0;
    return 'H' + Math.abs(h);
  }
  set(key, value, server_id=253) {
    const seq = this.next_seq++;
    const ph  = this.last_hash;
    const h   = this._hash(seq, key, value, ph);
    const rec = {seq, op:1, key, value, server_id,
                 prev_hash:ph, hash:h, is_tombstone:0,
                 timestamp: seq*1000};
    this.records.push(rec);
    this.last_hash = h;
    return seq;
  }
  delete(key, server_id=253) {
    const seq = this.next_seq++;
    const ph  = this.last_hash;
    const h   = this._hash(seq, key, '', ph);
    const rec = {seq, op:2, key, value:'', server_id,
                 prev_hash:ph, hash:h, is_tombstone:1,
                 timestamp: seq*1000};
    this.records.push(rec);
    this.last_hash = h;
    return seq;
  }
  get(key) {
    for(let i=this.records.length-1;i>=0;i--) {
      if(this.records[i].key===key) {
        if(this.records[i].is_tombstone) return {found:false};
        return {found:true, value:this.records[i].value,
                seq:this.records[i].seq};
      }
    }
    return {found:false};
  }
}

// FVX transfer — Mandate-DB 공리
function mandate_transfer(node, inputs) {
  const d = node.data;
  switch(node.type) {
    case 'SEQ_STATE':
      return {value: d.seq, lat: LAT.STABLE};

    case 'CHAIN_CONSTRAINT': {
      // prev_hash == records[i-1].hash
      if(!d.prev_hash || !d.expected_hash)
        return {value:null, lat:LAT.PARTIAL};
      if(d.prev_hash !== d.expected_hash)
        return {value:null, lat:LAT.TOP};   // 해시 불일치 = 위변조
      return {value:d.prev_hash, lat:LAT.STABLE};
    }

    case 'MONOTONE_CONSTRAINT': {
      // seq[i] == seq[i-1] + 1
      const src = inputs[0];
      if(!src||src.lat<LAT.STABLE) return {value:null, lat:LAT.PARTIAL};
      if(d.expected_seq !== undefined && src.value !== d.expected_seq)
        return {value:null, lat:LAT.TOP};  // seq 불연속 = Lost Update
      return {value:src.value, lat:LAT.STABLE};
    }

    case 'TOMBSTONE_CONSTRAINT': {
      // op==DELETE → is_tombstone==1
      if(d.op===2 && d.is_tombstone!==1)
        return {value:null, lat:LAT.TOP};
      if(d.op===1 && d.is_tombstone!==0)
        return {value:null, lat:LAT.TOP};
      return {value:d.op, lat:LAT.STABLE};
    }

    case 'OBSERVE':
      if(!inputs.every(n=>n&&n.lat>=LAT.STABLE))
        return {value:null, lat:LAT.PARTIAL};
      return {value:inputs[inputs.length-1]?.value, lat:LAT.STABLE};

    default:
      return {value:null, lat:LAT.STABLE};
  }
}

function build_mandate_graph(db) {
  const g = new IRGraph('MandateDB');
  const records = db.records;

  for(let i=0;i<records.length;i++) {
    const r = records[i];

    // SEQ 상태 노드
    const seq_n = g.node('SEQ_STATE', {seq: r.seq});

    // MONOTONE 제약 (i>0: seq 연속성)
    if(i>0) {
      const mono = g.node('MONOTONE_CONSTRAINT', {
        expected_seq: records[i-1].seq + 1
      });
      g.edge(seq_n, mono, 'CONSTRAINS');
    }

    // CHAIN 제약 (해시 체인 무결성)
    const expected_hash = i===0 ? 'GENESIS' : records[i-1].hash;
    const chain = g.node('CHAIN_CONSTRAINT', {
      prev_hash:     r.prev_hash,
      expected_hash: expected_hash,
    });
    g.edge(seq_n, chain, 'CONSTRAINS');

    // TOMBSTONE 제약
    const tomb = g.node('TOMBSTONE_CONSTRAINT', {
      op:           r.op,
      is_tombstone: r.is_tombstone,
    });
    g.edge(seq_n, tomb, 'CONSTRAINS');
  }

  const obs = g.node('OBSERVE', {});
  if(records.length>0) {
    const last_seq = g.nodes.get(g._nid-2);
    g.edge(last_seq.id, obs.id, 'PRODUCES');
  }
  g.edge(obs.id, obs.id, 'TERMINAL');
  return g;
}

