  ok('SET user:2 seq=2', s2===2, `seq=${s2}`);
  ok('SET user:1 seq=3 (update)', s3===3, `seq=${s3}`);
  ok('DELETE user:2 seq=4', s4===4, `seq=${s4}`);

  const r1 = db.get('user:1');
  const r2 = db.get('user:2');
  ok('GET user:1 = Alice2', r1.found && r1.value==='Alice2', r1.value);
  ok('GET user:2 = NotFound (tombstone)', !r2.found, 'tombstone 적용');

  // FVX 공리 검증
  const g1 = build_mandate_graph(db);
  const iter1 = solve(g1, mandate_transfer);
  const tops1 = top_nodes(g1);
  ok('FVX 공리 위반 없음', tops1.length===0,
