  // ── 시나리오 2: 해시 체인 위변조 감지 ────────────────
  console.log('\n[ S2 ] 해시 체인 위변조 감지');
  const db2 = new MandateDB();
  db2.set('secret', 'value_original', 253);
  db2.set('key2',   'data',           253);
  // 레코드 0의 hash를 임의 조작 (위변조 시뮬레이션)
  const original_hash = db2.records[0].hash;
  db2.records[0].hash = 'TAMPERED_HASH_XYZ';
  // → records[1].prev_hash는 여전히 original_hash
  //   CHAIN constraint: records[1].prev_hash != records[0].hash → TOP

  const g2 = build_mandate_graph(db2);
  const iter2 = solve(g2, mandate_transfer);
  const tops2 = top_nodes(g2);
  ok('위변조 → CHAIN constraint TOP 감지',
     tops2.length > 0,
     `TOP 노드 ${tops2.length}개`);
  console.log(`    위변조 경로: records[1].prev_hash="${db2.records[1].prev_hash}"`);
  console.log(`                 records[0].hash="${db2.records[0].hash}" (조작됨)`);
  console.log(`    → 불일치 → INCONSISTENT ✅`);
  // 복원
  db2.records[0].hash = original_hash;

  // ── 시나리오 3: seq 불연속 (Lost Update) 감지 ────────
  console.log('\n[ S3 ] seq 불연속 (Lost Update) 감지');
  const db3 = new MandateDB();
  db3.set('k1','v1',253);
  db3.set('k2','v2',253);
  // seq를 강제로 불연속으로 만들기
  db3.records[1].seq = 99;  // seq=2 → seq=99 (불연속)

  const g3 = build_mandate_graph(db3);
  const iter3 = solve(g3, mandate_transfer);
  const tops3 = top_nodes(g3);
  ok('seq 불연속 → MONOTONE constraint TOP 감지',
     tops3.length > 0,
     `TOP 노드 ${tops3.length}개`);

  // ── 시나리오 4: 대규모 로그 성능 ─────────────────────
  console.log('\n[ S4 ] 대규모 로그 성능 (N=500 레코드)');
  const db4 = new MandateDB();
  const t0 = performance.now();
  for(let i=0;i<500;i++) db4.set(`key:${i}`, `val:${i}`, 253);
  const build_t = performance.now()-t0;
  const g4 = build_mandate_graph(db4);
  const t1 = performance.now();
  const iter4 = solve(g4, mandate_transfer);
  const verify_t = performance.now()-t1;
  const tops4 = top_nodes(g4);
  ok(`N=500 무결성 검증`, tops4.length===0,
     `build=${build_t.toFixed(1)}ms verify=${verify_t.toFixed(1)}ms iter=${iter4}`);

  return results.every(r=>r.pass);
}

