  const tops1 = top_nodes(g1);
  ok('FVX 공리 위반 없음', tops1.length===0,
     `${iter1}회 수렴, 노드=${g1.nodes.size}`);

  // ── 시나리오 2: 해시 체인 위변조 감지 ────────────────
  console.log('\n[ S2 ] 해시 체인 위변조 감지');
  const db2 = new MandateDB();
  db2.set('secret', 'value_original', 253);
  db2.set('key2',   'data',           253);
  // 레코드 0의 hash를 임의 조작 (위변조 시뮬레이션)
  const original_hash = db2.records[0].hash;
