  const iter4 = solve(g4, mandate_transfer);
  const verify_t = performance.now()-t1;
  const tops4 = top_nodes(g4);
  ok(`N=500 무결성 검증`, tops4.length===0,
     `build=${build_t.toFixed(1)}ms verify=${verify_t.toFixed(1)}ms iter=${iter4}`);

  return results.every(r=>r.pass);
}

// ─────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════
// B. FreeJulia 정적 분석기 파이프라인
// ═══════════════════════════════════════════════════════
// ─────────────────────────────────────────────────────────

// FreeJulia Bytecode → FVX IR 브리지 (julia_bridge.fl 재현)
function julia_to_fvx(bytecodes) {
  const g = new IRGraph('FreeJulia::StaticAnalysis');
  const reg = new Map();  // register → node_id
  const type_map = new Map(); // node_id → inferred_type

  for(const {op, operands, result, type_hint} of bytecodes) {
    let node_id = null;

    if(op==='call') {
      const fn = operands[0];
      if(fn==='state') {
        node_id = g.node('IR_STATE', {
          state_id: parseInt(operands[1])||0,
          inferred_type: type_hint||'Int'
        });
        type_map.set(node_id, type_hint||'Int');

      } else if(fn==='observe') {
        node_id = g.node('IR_OBSERVE', {inferred_type: type_hint||'Any'});
        const src = reg.get(operands[1]);
        if(src!==undefined) {
          g.edge(src, node_id, 'PRODUCES');
          // 타입 일관성 체크 노드
          const tc = g.node('TYPE_CHECK', {
            expected: type_map.get(src)||'Any',
            got:      type_hint||'Any',
          });
          g.edge(node_id, tc, 'CONSTRAINS');
          type_map.set(node_id, type_map.get(src)||'Any');
        }

      } else if(fn==='evolve') {
        const dt = parseInt(operands[2])||1;
        node_id = g.node('IR_EVOLVE', {
          time_delta: dt,
          inferred_type: type_hint||'Int'
        });
        const src = reg.get(operands[1]);
        if(src!==undefined) g.edge(src, node_id, 'EVOLVES');

        // 깊이 제약
        const dc = g.node('DEPTH_CONSTRAINT', {
          current_depth: parseInt(operands[3])||1,
          max_depth: 100,
        });
        g.edge(node_id, dc, 'CONSTRAINS');
        type_map.set(node_id, type_hint||'Int');

      } else if(fn==='constrain') {
        node_id = g.node('IR_CONSTRAINT', {
          constraint_type: operands[1],
          inferred_type: type_hint||'Any',
        });
        const src = reg.get(operands[2]);
        if(src!==undefined) g.edge(src, node_id, 'CONSTRAINS');

      } else if(fn==='recurse') {
        // 재귀 호출 — DEPTH_CONSTRAINT로 모델링
        node_id = g.node('RECURSE_NODE', {
          fn_name: operands[1],
          depth:   parseInt(operands[2])||1,
        });
        const dc2 = g.node('DEPTH_CONSTRAINT', {
          current_depth: parseInt(operands[2])||1,
          max_depth: 100,
        });
        g.edge(node_id, dc2, 'CONSTRAINS');
      }

    } else if(op==='move') {
      // 레지스터 앨리어싱
      const src = reg.get(operands[0]);
      if(src!==undefined && result) {
        reg.set(result, src);
        type_map.set(src, type_map.get(src)||'Any');
        continue;
      }

    } else if(op==='ret') {
      const src = reg.get(operands[0]);
      if(src!==undefined) g.edge(src, src, 'TERMINAL');
      continue;
    }

    if(node_id && result) reg.set(result, node_id);
  }
  return g;
}

// FVX transfer — FreeJulia 정적 분석
function static_transfer(node, inputs) {
  const d = node.data;
  switch(node.type) {
    case 'IR_STATE':
      return {value: {v: d.state_id, type: d.inferred_type}, lat: LAT.STABLE};

    case 'IR_EVOLVE': {
      const src = inputs[0];
      if(!src||src.lat<LAT.STABLE) return {value:null, lat:LAT.PARTIAL};
      const val = src.value?.v;
      return {value:{v:(val||0)+d.time_delta, type:d.inferred_type}, lat:LAT.STABLE};
    }

    case 'IR_OBSERVE': {
      if(!inputs.every(n=>n&&n.lat>=LAT.STABLE))
        return {value:null, lat:LAT.PARTIAL};
      const last = inputs[inputs.length-1];
      return {value: last?.value, lat:LAT.STABLE};
    }

    case 'IR_CONSTRAINT': {
      const src = inputs[0];
      if(!src||src.lat<LAT.STABLE) return {value:null, lat:LAT.PARTIAL};
      const v = src.value?.v ?? 0;
      if(d.constraint_type==='NonNegative' && v<0)
        return {value:null, lat:LAT.TOP};
      if(d.constraint_type==='Positive' && v<=0)
        return {value:null, lat:LAT.TOP};
      return {value:src.value, lat:LAT.STABLE};
    }

    case 'TYPE_CHECK': {
      // 타입 불일치 감지
      if(d.expected!=='Any' && d.got!=='Any' && d.expected!==d.got)
        return {value:null, lat:LAT.TOP};  // 런타임 타입 에러
      return {value:d.expected, lat:LAT.STABLE};
    }

    case 'DEPTH_CONSTRAINT': {
      if(d.current_depth > d.max_depth)
        return {value:null, lat:LAT.TOP};  // 스택 오버플로
      return {value:d.current_depth, lat:LAT.STABLE};
    }

    case 'RECURSE_NODE': {
      if(d.depth > 100)
        return {value:null, lat:LAT.TOP};
      return {value:d.depth, lat:LAT.STABLE};
    }

    default:
      return {value:null, lat:LAT.STABLE};
  }
}

// DAG 순환 감지
function detect_cycle(g) {
  const visited=new Set(), stack=new Set();
  let found=false, path=[];
  function dfs(nid) {
    if(stack.has(nid)){found=true; path.push(nid); return;}
    if(visited.has(nid)) return;
    visited.add(nid); stack.add(nid);
    for(const e of g.edges.filter(e=>e.from===nid&&e.type!=='TERMINAL'))
      dfs(e.to);
    stack.delete(nid);
  }
  for(const [id] of g.nodes) dfs(id);
  return {found, path};
}

function test_freejulia_static() {
  console.log('\n╔' + '═'.repeat(56) + '╗');
  console.log('║  B. FreeJulia 정적 분석기 파이프라인' + ' '.repeat(18) + '║');
  console.log('╚' + '═'.repeat(56) + '╝');

  const results = [];
  const ok = (label, pass, detail='') => {
    results.push({label,pass});
    console.log(`  ${pass?'✅':'❌'} ${label}${detail?' ('+detail+')':''}`);
    return pass;
  };

  // ── P1: 타입 안전 코드 ───────────────────────────────
  console.log('\n[ P1 ] 타입 안전 코드 — 런타임 에러 없음 증명');
  const safe_code = [
    {op:'call', operands:['state','42'],    result:'r0', type_hint:'Int'},
    {op:'call', operands:['constrain','NonNegative','r0'], result:'r1', type_hint:'Int'},
    {op:'call', operands:['evolve','r1','10','1'], result:'r2', type_hint:'Int'},
    {op:'call', operands:['observe','r2'], result:'r3', type_hint:'Int'},
    {op:'ret',  operands:['r3']},
  ];
  const g_safe = julia_to_fvx(safe_code);
  solve(g_safe, static_transfer);
  const {found:c1} = detect_cycle(g_safe);
  const tops_safe = top_nodes(g_safe);
  ok('타입 일관성 (Int→Int)', tops_safe.filter(n=>n.type==='TYPE_CHECK').length===0);
  ok('스택 깊이 안전 (depth=1 ≤ 100)', tops_safe.filter(n=>n.type==='DEPTH_CONSTRAINT').length===0);
  ok('DAG 확인 (순환 없음)', !c1);
  ok('전체 정적 안전', tops_safe.length===0, `노드=${g_safe.nodes.size}`);

  // ── P2: 타입 불일치 감지 ─────────────────────────────
  console.log('\n[ P2 ] 타입 불일치 — 컴파일 전 에러 감지');
  const type_err_code = [
    {op:'call', operands:['state','42'],    result:'r0', type_hint:'Int'},
    {op:'call', operands:['observe','r0'], result:'r1', type_hint:'String'}, // Int→String 불일치
    {op:'ret',  operands:['r1']},
  ];
  const g_type = julia_to_fvx(type_err_code);
  solve(g_type, static_transfer);
  const tops_type = top_nodes(g_type);
  const type_violations = tops_type.filter(n=>n.type==='TYPE_CHECK');
  ok('Int→String 불일치 → TOP 감지', type_violations.length>0,
     `TYPE_CHECK 위반 ${type_violations.length}개`);

  // ── P3: 스택 깊이 초과 감지 ──────────────────────────
  console.log('\n[ P3 ] 스택 깊이 초과 — 오버플로 사전 차단');
  const deep_code = [];
  for(let d=1;d<=105;d++) {  // MAX_CALL_DEPTH=100 초과
    deep_code.push({
      op:'call', operands:['recurse',`fn_${d}`,`${d}`], result:`r${d}`
    });
  }
  deep_code.push({op:'ret', operands:['r1']});
  const g_deep = julia_to_fvx(deep_code);
  solve(g_deep, static_transfer);
  const tops_deep = top_nodes(g_deep);
  const depth_viol = tops_deep.filter(n=>n.type==='DEPTH_CONSTRAINT');
  ok('depth=105 > 100 → TOP 감지', depth_viol.length>0,
     `DEPTH_CONSTRAINT 위반 ${depth_viol.length}개`);

  // ── P4: code_generator.fl 실제 패턴 검증 ─────────────
  console.log('\n[ P4 ] code_generator.fl 실제 패턴 (observe→consume 체인)');
  // FreeJulia code_generator.fl에서 실제 생성되는 패턴
  const cg_pattern = [
    {op:'call', operands:['state','1'],         result:'r0', type_hint:'Int'},
    {op:'call', operands:['constrain','NonNegative','r0'], result:'r1', type_hint:'Int'},
    {op:'call', operands:['evolve','r1','5','1'], result:'r2', type_hint:'Int'},
    {op:'move', operands:['r2'],                result:'r3'},
    {op:'call', operands:['observe','r3'],      result:'r4', type_hint:'Int'},
    {op:'call', operands:['state','100'],       result:'r5', type_hint:'Int'},
    {op:'call', operands:['constrain','Positive','r5'], result:'r6', type_hint:'Int'},
    {op:'call', operands:['observe','r6'],      result:'r7', type_hint:'Int'},
    {op:'ret',  operands:['r7']},
  ];
  const g_cg = julia_to_fvx(cg_pattern);
  const iters_cg = solve(g_cg, static_transfer);
  const {found:c4} = detect_cycle(g_cg);
  const tops_cg = top_nodes(g_cg);
  ok('code_generator 패턴 안전', tops_cg.length===0,
     `노드=${g_cg.nodes.size} iter=${iters_cg}`);
  ok('DAG 확인', !c4);

  // ── P5: 대규모 FL 파일 시뮬레이션 (N=200 함수) ───────
  console.log('\n[ P5 ] 대규모 FL 파일 시뮬레이션 (함수 200개)');
  const large_code = [];
  for(let i=0;i<200;i++) {
    large_code.push({op:'call',operands:['state',`${i}`],result:`r${i*4}`,type_hint:'Int'});
    large_code.push({op:'call',operands:['evolve',`r${i*4}`,`${i%10+1}`,`${i%5+1}`],result:`r${i*4+1}`,type_hint:'Int'});
    large_code.push({op:'call',operands:['observe',`r${i*4+1}`],result:`r${i*4+2}`,type_hint:'Int'});
  }
  large_code.push({op:'ret',operands:['r0']});
  const t0 = performance.now();
  const g_large = julia_to_fvx(large_code);
  const iters_large = solve(g_large, static_transfer);
  const elapsed = performance.now()-t0;
  const tops_large = top_nodes(g_large);
  ok(`200개 함수 정적 분석 완료`, tops_large.length===0,
     `${elapsed.toFixed(1)}ms iter=${iters_large} 노드=${g_large.nodes.size}`);

  return results.every(r=>r.pass);
}

// ─────────────────────────────────────────────────────────
// 최종 집계
// ─────────────────────────────────────────────────────────
const r_mandate = test_mandate_db();
const r_julia   = test_freejulia_static();

console.log('\n╔' + '═'.repeat(56) + '╗');
console.log('║  FVX 연동 통합 테스트 — 최종 결과' + ' '.repeat(21) + '║');
console.log('╚' + '═'.repeat(56) + '╝');
console.log(`  ${r_mandate?'✅':'❌'} A. Mandate-DB 트랜잭션 공리 검증`);
console.log(`  ${r_julia  ?'✅':'❌'} B. FreeJulia 정적 분석기 파이프라인`);
console.log('─'.repeat(58));
const total = (r_mandate?1:0)+(r_julia?1:0);
console.log(`  ${total}/2 PASS  ${total===2?'🎉 전체 통과':''}`);
console.log('═'.repeat(58));

