# ============================================================================
# Part 1: Token 정의
# ============================================================================

record Token {
  kind:   String,   # 토큰 종류
  lexeme: String,   # 원문
  line:   Int,
  col:    Int,
}

function new_token(kind: String, lexeme: String, line: Int, col: Int): Token =
  Token { kind = kind, lexeme = lexeme, line = line, col = col }

# 기본
let TK_EOF        = "EOF"
let TK_IDENT      = "IDENT"
let TK_INT        = "INT"
let TK_FLOAT      = "FLOAT"
let TK_STRING     = "STRING"
