	if size < 1 { size = 1 }
	addr := e.MemPtr
	e.MemPtr += size
	for len(e.Memory) < e.MemPtr {
		e.Memory = append(e.Memory, rInt(0))
	}
	return addr
}

func (e *Env) load(addr int) RVal {
	if addr < 0 || addr >= len(e.Memory) { return rInt(0) }

